import numpy as np


class FeasibilityCoordProbeMIDEv15:
    """
    Mixed-integer constrained optimiser (v15), refining v13:
    - Deb's feasibility rules for all selection decisions.
    - Cached evaluator: repeated integer points cost no budget.
    - current-to-pbest/1 DE with external archive and jDE-style F/CR adaptation.
    - Incumbent local search (Hooke-Jeeves style):
        * per-coordinate expansion multipliers in [1.2, 6].
        * chained expansions along successful directions (up to 8 links).
        * failed coordinate step -> reverse probe whose multiplier adapts (v15).
    - Stall-triggered heavy-tailed kick whose scale doubles on failed escapes
      and resets to the base scale after an incumbent improvement (v15).
    - Per-coordinate 1/5th-rule step sizes with partial re-inflation at restarts.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float).reshape(d)
        ub = np.asarray(func.bounds.ub, dtype=float).reshape(d)
        span = ub - lb

        vtypes = list(func.variable_types)
        is_int = np.array([vt != "continuous" for vt in vtypes], dtype=bool)
        is_cont = ~is_int
        iidx = np.where(is_int)[0]
        cidx = np.where(is_cont)[0]
        nvals = np.ones(d, dtype=int)
        for i in iidx:
            nvals[i] = int(func.n_values[i])

        self.used = 0
        self.best_x = None
        self.best_f = np.inf
        self.inf_x = None
        self.inf_f = np.inf
        self.inf_v = np.inf
        self.elite = []
        cache = {}

        p_pat = [0.3, 0, 0]
        p_ext = [0.15, 0, 0]
        emult = np.full(d, 2.0)
        rev = [-0.5]          # adaptive reverse-probe multiplier (negative)
        MAX_CHAIN = 8
        pending = [None]
        kick_scale = [0.01]   # adaptive heavy-tailed kick scale

        def repair(x):
            x = np.clip(x, lb, ub)
            if iidx.size:
                x[iidx] = np.clip(np.rint(x[iidx]), 0, nvals[iidx] - 1)
            return x

        def ev(x):
            x = repair(np.asarray(x, dtype=float))
            key = x.tobytes()
            if key in cache:
                f, v = cache[key]
                return f, v, x
            if self.used >= self.budget:
                raise RuntimeError("budget exhausted")
            f, g = func(x)
            self.used += 1
            f = float(f)
            g = np.atleast_1d(np.asarray(g, dtype=float))
            g = np.nan_to_num(g, nan=1e6, posinf=1e6, neginf=0.0)
            v = float(np.sum(np.maximum(g, 0.0)))
            if not np.isfinite(f):
                f = np.inf
                v = max(v, 1e-9)
            cache[key] = (f, v)
            if v == 0.0:
                if f < self.best_f:
                    self.best_f = f
                    self.best_x = x.copy()
                self.elite.append((f, x.copy()))
                self.elite.sort(key=lambda t: t[0])
                del self.elite[12:]
            else:
                if v < self.inf_v or (v == self.inf_v and f < self.inf_f):
                    self.inf_v, self.inf_f = v, f
                    self.inf_x = x.copy()
            return f, v, x

        def rank_key(f, v):
            return (0, f) if v == 0.0 else (1, v)

        def worst_key(f, v):
            # larger tuple = worse (infeasible worse than feasible; by violation / objective)
            return (1, v) if v > 0.0 else (0, f)

        def base_point():
            if self.best_x is not None:
                return self.best_x, (0, self.best_f)
            if self.inf_x is not None:
                return self.inf_x, (1, self.inf_v)
            return None, None

        def better(a, b):
            if a[1] == 0.0 and b[1] == 0.0:
                return a[0] < b[0]
            if a[1] == 0.0 or b[1] == 0.0:
                return a[1] == 0.0
            return a[1] < b[1]

        def lhs(n):
            u = np.empty((n, d))
            for j in range(d):
                u[:, j] = (rng.permutation(n) + rng.random(n)) / n
            return repair(lb + u * span)

        def perturb(scale, center):
            x = center.copy()
            x[cidx] += scale * span[cidx] * rng.standard_normal(cidx.size)
            if iidx.size:
                reset = is_int & (rng.random(d) < max(0.05, 0.3 * scale))
                if reset.any():
                    x[reset] = rng.integers(0, nvals[reset])
            return repair(x)

        def kick(center, s):
            x = center.copy()
            if cidx.size:
                c = np.clip(rng.standard_cauchy(cidx.size), -5, 5)
                mask = rng.random(cidx.size) < 0.5
                x[cidx] += s * span[cidx] * c * mask
            if iidx.size:
                flip = is_int & (rng.random(d) < 0.15)
                if flip.any():
                    x[flip] = rng.integers(0, nvals[flip])
            return repair(x)

        sig = np.full(d, 0.1)
        disp = np.zeros(d)
        last_step = np.zeros(d)

        def local_search(steps):
            nonlocal disp, last_step
            for _ in range(steps):
                if self.used >= self.budget:
                    return
                b, bk = base_point()
                if b is None:
                    return

                use_pattern = bool(np.any(disp[cidx])) and rng.random() < p_pat[0]
                use_ext = (not use_pattern) and bool(np.any(last_step[cidx])) \
                    and rng.random() < p_ext[0]

                cand = b.copy()
                ks = np.array([], dtype=int)
                probe = False
                kind = None
                chain = 0
                if use_pattern:
                    cand[cidx] += disp[cidx] * rng.uniform(0.5, 1.5)
                elif use_ext:
                    cand[cidx] += last_step[cidx] * rng.uniform(1.5, 2.5)
                elif pending[0] is not None:
                    j, dl, kind, chain = pending[0]
                    pending[0] = None
                    mult = emult[j] if kind == "exp" else rev[0]
                    cand[j] = b[j] + mult * dl
                    ks = np.array([j], dtype=int)
                    probe = True
                else:
                    kmax = 1 if (self.best_x is None and rng.random() < 0.5) else min(3, d)
                    k = int(rng.integers(1, kmax + 1))
                    ks = rng.choice(d, k, replace=False)
                    for j in ks:
                        if is_int[j]:
                            if rng.random() < 0.6:
                                cand[j] = cand[j] + rng.choice([-1.0, 1.0])
                            else:
                                cand[j] = rng.integers(0, nvals[j])
                        else:
                            cand[j] += sig[j] * span[j] * rng.standard_normal()

                f, v, x = ev(cand)
                success = rank_key(f, v) < bk

                if use_pattern:
                    p_pat[2] += 1
                    if success:
                        p_pat[1] += 1
                        disp = disp * 1.5
                    else:
                        disp = disp * 0.5
                        if np.max(np.abs(disp[cidx]) / np.maximum(span[cidx], 1e-12)) < 1e-6:
                            disp = np.zeros(d)
                    if p_pat[2] >= 10:
                        rate = (p_pat[1] + 0.5) / (p_pat[2] + 1.0)
                        p_pat[0] = float(np.clip(0.1 + 0.8 * rate, 0.1, 0.6))
                        p_pat[1] = 0
                        p_pat[2] = 0
                elif use_ext:
                    p_ext[2] += 1
                    if success:
                        p_ext[1] += 1
                    if p_ext[2] >= 10:
                        rate = (p_ext[1] + 0.5) / (p_ext[2] + 1.0)
                        p_ext[0] = float(np.clip(0.05 + 0.6 * rate, 0.05, 0.5))
                        p_ext[1] = 0
                        p_ext[2] = 0
                else:
                    if probe:
                        j = int(ks[0])
                        if kind == "exp":
                            if success:
                                emult[j] = min(6.0, emult[j] * 1.3)
                            else:
                                emult[j] = max(1.2, emult[j] * 0.7)
                        else:
                            # adaptive reverse multiplier in [-1.0, -0.2]
                            if success:
                                rev[0] = max(-1.0, rev[0] * 1.2)
                            else:
                                rev[0] = min(-0.2, rev[0] * 0.8)
                    if success:
                        disp = np.zeros(d)
                        disp[cidx] = (x - b)[cidx]
                        last_step = np.zeros(d)
                        last_step[cidx] = (x - b)[cidx]
                        if probe and kind == "exp" and chain < MAX_CHAIN:
                            j = int(ks[0])
                            dl = float(x[j] - b[j])
                            if dl != 0.0:
                                pending[0] = (j, dl, "exp", chain + 1)
                        elif (not probe) and ks.size == 1 and is_cont[ks[0]]:
                            j = int(ks[0])
                            dl = float(x[j] - b[j])
                            if dl != 0.0:
                                pending[0] = (j, dl, "exp", 0)
                    elif (not probe) and ks.size == 1 and is_cont[ks[0]]:
                        j = int(ks[0])
                        dl = float(x[j] - b[j])
                        if dl != 0.0:
                            pending[0] = (j, dl, "rev", 0)
                    for j in ks:
                        if is_cont[j]:
                            if success:
                                sig[j] = min(0.5, sig[j] * 1.4)
                            else:
                                sig[j] = max(1e-5, sig[j] * 0.9)

        base_np = min(int(np.clip(5 * d, 20, 80)), max(6, self.budget // 10))
        ls_steps = max(5, 3 * d)
        restart_id = 0

        while self.used < self.budget:
            NP = int(min(base_np * (2 ** min(restart_id // 2, 2)), max(6, self.budget // 6)))
            NP = max(NP, 4)
            if self.best_x is None:
                NP = max(4, NP // 2)
            patience = 20 if self.best_x is None else 30

            center, _ = base_point()
            lhs_pts = lhs(NP)
            if restart_id % 2 == 1 and center is not None:
                scale = 0.2 * (0.5 ** min(restart_id, 6)) + 0.01
                anchors = [e[1] for e in self.elite] if self.elite else [center]
                init = []
                for k in range(NP):
                    if rng.random() < 0.5:
                        a = anchors[int(rng.integers(len(anchors)))]
                        init.append(perturb(scale * (0.5 + rng.random()), a))
                    else:
                        init.append(lhs_pts[k])
                sig = np.clip(sig * 1.5, 1e-3, 0.5)
            else:
                init = list(lhs_pts)
                if center is not None and restart_id > 0:
                    init[0] = center.copy()
            restart_id += 1

            pending[0] = None
            X = np.zeros((NP, d))
            PF = np.zeros(NP)
            PV = np.zeros(NP)
            for k in range(NP):
                if self.used >= self.budget:
                    return self.best_f, self.best_x
                f, v, x = ev(init[k])
                X[k], PF[k], PV[k] = x, f, v

            Fa = np.full(NP, 0.6)
            CRa = np.full(NP, 0.9)
            archive = []
            stall = 0
            kicked = False

            while True:
                used_before = self.used
                prog_before = (self.best_f, self.inf_v)
                order = sorted(range(NP), key=lambda k: rank_key(PF[k], PV[k]))
                ptop = max(2, int(0.15 * NP))

                for i in range(NP):
                    if self.used >= self.budget:
                        return self.best_f, self.best_x
                    if rng.random() < 0.1:
                        Fa[i] = 0.1 + 0.9 * rng.random()
                    if rng.random() < 0.1:
                        CRa[i] = rng.random()
                    F = Fa[i]

                    pb = order[int(rng.integers(ptop))]

                    while True:
                        r1 = int(rng.integers(NP))
                        if r1 != i:
                            break
                    while True:
                        r2 = int(rng.integers(NP + len(archive)))
                        if r2 < NP and (r2 == i or r2 == r1):
                            continue
                        break
                    x_r2 = X[r2] if r2 < NP else archive[r2 - NP]

                    mutant = X[i] + F * (X[pb] - X[i]) + F * (X[r1] - x_r2)

                    mask = rng.random(d) < CRa[i]
                    mask[rng.integers(d)] = True
                    trial = np.where(mask, mutant, X[i])

                    rs = mask & is_int & (rng.random(d) < 1.0 / max(d, 1))
                    if rs.any():
                        trial[rs] = rng.integers(0, nvals[rs])

                    f, v, x = ev(trial)
                    if better((f, v), (PF[i], PV[i])):
                        archive.append(X[i].copy())
                        if len(archive) > NP:
                            archive.pop(int(rng.integers(len(archive))))
                        X[i], PF[i], PV[i] = x, f, v

                if self.best_x is not None or self.inf_x is not None:
                    steps = ls_steps * 2 if self.best_x is None else int(ls_steps * 1.5)
                    local_search(steps)

                # stall-triggered kick on incumbent (once per stall episode)
                if stall >= patience // 2 and not kicked and self.best_x is not None:
                    kicked = True
                    best_before_kick = self.best_f
                    for _ in range(3):
                        if self.used >= self.budget:
                            return self.best_f, self.best_x
                        kf, kv, kx = ev(kick(self.best_x, kick_scale[0]))
                        worst = max(range(NP), key=lambda k: worst_key(PF[k], PV[k]))
                        if better((kf, kv), (PF[worst], PV[worst])):
                            X[worst], PF[worst], PV[worst] = kx, kf, kv
                    if self.best_f < best_before_kick:
                        kick_scale[0] = 0.01
                    else:
                        kick_scale[0] = min(0.2, kick_scale[0] * 2.0)

                prog_after = (self.best_f, self.inf_v)
                if prog_after < prog_before:
                    stall = 0
                    kicked = False
                else:
                    stall += 1
                if self.used == used_before or stall >= patience:
                    break

        return self.best_f, self.best_x
